sketch matmul_transposed {
  symbols: M, N, K;
  tensors: A[K, M]: f16; B[N, K]: f16; C[M, N]: f32;

  constexpr: BM = 128, BN = 256, BK = 64

  @llm_hint("parallel", "grididx.x")
  for i_outer in range(0, M, BM):
    @llm_hint("parallel", "grididx.y")
    for j_outer in range(0, N, BN):

      c_acc = alloc([BM, BN], llm_hint=["fastest", "accumulator", "init_zero"])
      a_tile = alloc([BK, BM], llm_hint=["fast", "input_cache", "shared_between_threads"])
      b_tile = alloc([BN, BK], llm_hint=["fast", "input_cache", "shared_between_threads"])

      @llm_hint("pipeline")
      for k_outer in range(0, K, BK):

        load(A[k_outer:k_outer+BK, i_outer:i_outer+BM] -> a_tile)
        load(B[j_outer:j_outer+BN, k_outer:k_outer+BK] -> b_tile)

        gemm(a_tile, b_tile, dst=c_acc)

      store(c_acc -> C[i_outer:i_outer+BM, j_outer:j_outer+BN])
}

