sketch matmul_transeposed_both {
  symbols: M, N, K;
  tensors: A[K, M]: f16; B[N, K]: f16; C[M, N]: f32;

  constexpr: m0 = 64, n0 = 128, k0 = 32

  @llm_hint("parallel", "grididx.x")
  for i_outer in range(0, ceil(M, m0)):
    @llm_hint("parallel", "grididx.y")
    for j_outer in range(0, ceil(N, n0)):

      # 分配累加器到最快内存（寄存器）
      c_tile = alloc([m0, n0], llm_hint=["fastest", "accumulator", "init_zero"])

      @llm_hint("pipeline")
      for k_outer in range(0, ceil(K, k0)):
        # 分配输入tile到快速内存（shared memory）
        a_tile = alloc([m0, k0], llm_hint=["fast", "input_cache"])
        b_tile = alloc([k0, n0], llm_hint=["fast", "input_cache"])

        # 加载转置后的数据块：A.T 和 B.T
        load(A[k_outer:k_outer+k0, i_outer:i_outer+m0] -> a_tile)
        load(B[j_outer:j_outer+n0, k_outer:k_outer+k0] -> b_tile)

        # 矩阵乘法累加
        gemm(a_tile, b_tile, dst=c_tile)

      # 存储结果到输出张量
      store(c_tile -> C[i_outer:i_outer+m0, j_outer:j_outer+n0])
}
